{"command": "cat > /workspace/load_samples.py << 'PYEOF'
import json

with open('/workspace/samples.json', 'r') as f:
    samples = json.load(f)

# Generate ft2 batch commands
batch = []
for inst, b64 in samples.items():
    batch.append({
        "name": "sample_create_from_pcm",
        "arguments": {
            "instrument": inst,
            "sample": 0,
            "pcm": b64,
            "encoding": "int16",
            "name": f"Sample{inst}"
        }
    })
    # Set instrument name
    batch.append({
        "name": "instrument_set",
        "arguments": {
            "instrument": inst,
            "name": f"Inst{inst}"
        }
    })
    # Set sample metadata - volume, loop settings
    batch.append({
        "name": "sample_set",
        "arguments": {
            "instrument": inst,
            "sample": 0,
            "volume": 64,
            "panning": 128,
            "loop_start": 0,
            "loop_length": 0,
            "flags": 3 if inst < 3 else 0  # Loop for melodic instruments (0,1,2,7,8)
        }
    })

with open('/workspace/load_samples_batch.json', 'w') as f:
    json.dump(batch, f)

print("Batch file created")
